custom_css:
/* Author: @jiuyi0204 | 第37层观测档案 | 未经作者明确许可，禁止二次修改、二次上传、转载、重新打包或冒名发布。 */

/* ===== src/tokens.css ===== */
/* Author: @jiuyi0204 | 第37层观测档案视觉令牌。未经许可禁止二改二传。 */
@font-face {
    font-family: "Huiwen-mincho";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/huiwenmincho-improved/HuiwenMincho-Improved-Regular.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    --theme-bg-deep: #2b4033;
    --theme-bg-deeper: #213127;
    --theme-surface: #e8e0d0;
    --theme-surface-light: #f0ebdf;
    --theme-surface-muted: #d9cfba;
    --theme-surface-disabled: #c9bea7;
    --theme-surface-translucent: rgba(232, 224, 208, 0.96);
    --theme-dark-translucent: rgba(43, 64, 51, 0.96);
    --theme-text-primary: #302b20;
    --theme-text-secondary: #5d5035;
    --theme-text-disabled: #685f49;
    --theme-text-on-dark: #ead9ad;
    --theme-text-on-dark-muted: #cfbd8f;
    --theme-ink-green: #294536;
    --theme-ink-green-soft: #456753;
    --theme-brass: #a9823f;
    --theme-brass-light: #d4b567;
    --theme-rust: #8c4e31;
    --theme-border: #6d5633;
    --theme-border-soft: rgba(109, 86, 51, 0.55);
    --theme-focus-ring: #e3bf63;
    --theme-selection: #c7a75b;
    --theme-info: #547282;
    --theme-success: #557557;
    --theme-warning: #a86f2f;
    --theme-error: #93463b;
    --theme-opacity-disabled: 0.82;
    --theme-opacity-muted: 0.88;
    --theme-opacity-full: 1;
    --theme-filter-none: none;
    --theme-text-shadow-none: none;
    --theme-shadow-none: none;
    --theme-overflow-x: auto;
    --theme-shadow: 0 12px 28px rgba(26, 38, 30, 0.34);
    --theme-shadow-soft: 0 5px 14px rgba(26, 38, 30, 0.24);
    --theme-shadow-lift: 0 0.35rem 0.45rem rgba(25, 35, 28, 0.34), 0 1.1rem 1.8rem rgba(25, 35, 28, 0.28);
    --theme-shadow-inset: inset 0 0 0 1px rgba(220, 188, 102, 0.35), inset 0 0.45rem 0.8rem rgba(255, 240, 187, 0.16), inset 0 -0.5rem 0.8rem rgba(31, 45, 36, 0.32);
    --theme-radius-sm: 0.25rem;
    --theme-radius-md: 0.5rem;
    --theme-radius-lg: 0.85rem;
    --theme-gap-xs: 0.3rem;
    --theme-gap-sm: 0.55rem;
    --theme-gap-md: 0.85rem;
    --theme-gap-lg: 1.25rem;
    --theme-speed: 160ms;
    --theme-font-body: "Huiwen-mincho", "Source Han Serif SC", "Noto Serif SC", SimSun, serif;
    --theme-font-display: "Huiwen-mincho", "Source Han Serif SC", "Noto Serif SC", SimSun, serif;
    --theme-font-ui: "Huiwen-mincho", "Source Han Serif SC", "Noto Serif SC", SimSun, serif;
    --theme-font-size-body: 1.04em;
    --theme-font-size-user: 1em;
    --theme-font-size-character: 1.07em;
    --theme-font-size-meta: 0.82em;
    --theme-font-size-input: 0.96em;
    --theme-avatar-size: 8rem;
    --theme-avatar-gap: 0.75rem;
    --theme-avatar-slot: calc(var(--theme-avatar-size) + var(--theme-avatar-gap));
    --theme-city-height: 10.4rem;
    --theme-floor-pad: clamp(0.95rem, 3vw, 2.6rem);
    --st-theme-mobile-reading-width: 100%;
    --st-theme-mobile-reading-padding: 0.8rem;
    --theme-city-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/ce1cd56bcb34f394cd90079e7bf32a4033ca0afb/assets/%E7%AC%AC37%E5%B1%82%E8%A7%82%E6%B5%8B%E6%A1%A3%E6%A1%88/city-skyline-cutout-light-v2.png");
    --theme-paper-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/ce1cd56bcb34f394cd90079e7bf32a4033ca0afb/assets/%E7%AC%AC37%E5%B1%82%E8%A7%82%E6%B5%8B%E6%A1%A3%E6%A1%88/parchment-texture-light-v2.png");
    --theme-footer-ornament: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/ce1cd56bcb34f394cd90079e7bf32a4033ca0afb/assets/%E7%AC%AC37%E5%B1%82%E8%A7%82%E6%B5%8B%E6%A1%A3%E6%A1%88/message-footer-ornament-cutout.png");
}

/* ===== src/kernel/safety.css ===== */
/* 功能保护：装饰层不拦截，交互节点保留原事件与焦点。 */
#chat .mes_block::before,
#top-bar::after,
#send_form::before {
    pointer-events: none;
}

#chat .mes_buttons,
#chat .mes_edit_buttons,
#chat .mes_reasoning_actions,
#send_form :is(#leftSendForm, #rightSendForm),
#top-settings-holder > .drawer > .drawer-toggle {
    pointer-events: auto;
}

/* ===== src/kernel/scrollbars.css ===== */
/*
 * v6 固定无滚动条外观内核。
 * 仅隐藏浏览器轨道/拇指，不修改 overflow、touch-action、pointer-events，
 * 不隐藏滚动容器、跳转键、功能按钮或 input[type="range"]。
 */
:where(
    html,
    body,
    #sheld,
    #sheld *,
    #chat,
    .drawer-content,
    .popup-content,
    .scrollable,
    .select2-results__options,
    #send_textarea,
    #chat .mes_text pre,
    #chat .mes_text .table-responsive
) {
    scrollbar-width: none;
    -ms-overflow-style: none;
}

:where(
    html,
    body,
    #sheld,
    #sheld *,
    #chat,
    .drawer-content,
    .popup-content,
    .scrollable,
    .select2-results__options,
    #send_textarea,
    #chat .mes_text pre,
    #chat .mes_text .table-responsive
)::-webkit-scrollbar {
    width: 0;
    height: 0;
}

/* ===== src/chat-layout.css ===== */
/*
 * A图母版重建：深绿聊天底承载逐消息独立档案卡。
 * Character使用真实头像/姓名/时间/消息序号；User保持独立题签。
 */
body {
    background-color: var(--theme-bg-deeper);
    color: var(--theme-text-primary);
    font-family: var(--theme-font-ui);
}

#chat {
    padding: clamp(0.55rem, 1.2vw, 1rem);
    color: var(--theme-text-primary);
    background-color: var(--theme-bg-deep);
    background-image:
        linear-gradient(90deg, var(--theme-border-soft) 1px, transparent 1px),
        linear-gradient(180deg, var(--theme-border-soft) 1px, transparent 1px);
    background-size: 5rem 5rem;
    border: 1px solid var(--theme-border);
    box-shadow: var(--theme-shadow);
    text-shadow: none;
}

#chat .mes {
    position: relative;
    color: var(--theme-text-primary);
}

#chat .mes[is_user="false"][is_system="false"] {
    display: flex;
    align-items: stretch;
    width: calc(100% - clamp(0.5rem, 1.4vw, 1.35rem));
    margin: clamp(0.8rem, 1.8vw, 1.35rem) auto;
    padding: 0;
}

#chat .mes[is_user="false"][is_system="false"] .mes_block {
    position: relative;
    flex: 1 1 auto;
    width: 100%;
    min-width: 0;
    padding: calc(var(--theme-city-height) + 4.45rem) var(--theme-floor-pad) 1.35rem;
    color: var(--theme-text-primary);
    background-color: var(--theme-surface);
    background-image:
        var(--theme-city-image),
        var(--theme-paper-image),
        linear-gradient(180deg, var(--theme-surface-light) 0 var(--theme-city-height), var(--theme-surface) var(--theme-city-height));
    background-position: top center, center, center;
    background-size: 100% var(--theme-city-height), 30rem 30rem, 100% 100%;
    background-repeat: no-repeat, repeat, no-repeat;
    background-blend-mode: normal, multiply, normal;
    border: 1px solid var(--theme-border);
    border-radius: var(--theme-radius-sm);
    box-shadow:
        0 0.2rem 0 var(--theme-brass),
        0 0.72rem 1.35rem rgba(18, 29, 23, 0.34),
        inset 0 0 0 1px rgba(233, 216, 169, 0.28);
    overflow-x: clip;
    overflow-y: visible;
}

#chat .mes[is_user="false"][is_system="false"] .mes_block::after {
    content: "";
    position: absolute;
    z-index: 0;
    inset: 0.34rem;
    border: 1px solid var(--theme-border-soft);
    border-radius: calc(var(--theme-radius-sm) * 0.7);
    pointer-events: none;
}

#chat .mes[is_user="false"][is_system="false"] .mes_block::before {
    content: "观测记录";
    position: absolute;
    z-index: 2;
    inset-block-start: calc(var(--theme-city-height) + 0.52rem);
    inset-inline-end: 1.05rem;
    min-width: 5.7rem;
    padding: 0.24rem 0.58rem;
    color: var(--theme-ink-green);
    background-color: var(--theme-surface-muted);
    background-image: var(--theme-paper-image);
    background-size: 18rem 18rem;
    background-blend-mode: multiply;
    border: 1px solid var(--theme-border);
    font-family: var(--theme-font-display);
    font-size: var(--theme-font-size-meta);
    letter-spacing: 0.14em;
    text-align: center;
    box-shadow: var(--theme-shadow-soft);
    pointer-events: none;
}

#chat .mes[is_user="false"][is_system="false"] .mesAvatarWrapper {
    position: absolute;
    z-index: 4;
    inset-block-start: calc(var(--theme-city-height) - (var(--theme-avatar-size) * 0.5));
    inset-inline-end: clamp(6.4rem, 12%, 8.6rem);
    width: var(--theme-avatar-size);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--theme-gap-xs);
}

#chat .mes[is_user="false"][is_system="false"] .avatar {
    width: var(--theme-avatar-size);
    height: var(--theme-avatar-size);
    flex: 0 0 var(--theme-avatar-size);
    border-radius: 50%;
    box-sizing: border-box;
}

#chat .mes[is_user="false"][is_system="false"] .avatar img {
    width: 100%;
    height: 100%;
    border-radius: 50%;
    box-sizing: border-box;
}

#chat .mes[is_user="false"][is_system="false"] .avatar {
    position: relative;
    padding: 0.4rem;
    background-color: var(--theme-bg-deep);
    border: 0.28rem double var(--theme-brass-light);
    outline: 0.15rem solid var(--theme-border);
    outline-offset: 0.16rem;
    box-shadow: var(--theme-shadow-lift), var(--theme-shadow-inset);
}

#chat .mes[is_user="false"][is_system="false"] .avatar::before,
#chat .mes[is_user="false"][is_system="false"] .avatar::after {
    content: "";
    position: absolute;
    border-radius: 50%;
    pointer-events: none;
}

#chat .mes[is_user="false"][is_system="false"] .avatar::before {
    inset: -0.38rem;
    border: 0.1rem solid var(--theme-brass-light);
    box-shadow: inset 0 0 0 0.12rem var(--theme-bg-deep);
}

#chat .mes[is_user="false"][is_system="false"] .avatar::after {
    inset: -0.7rem;
    border: 0.1rem solid var(--theme-brass);
    box-shadow: 0 0.65rem 1.15rem rgba(18, 29, 23, 0.42);
}

#chat .mes[is_user="false"][is_system="false"] .avatar img {
    position: relative;
    z-index: 1;
    object-fit: cover;
    border: 1px solid var(--theme-border);
    box-shadow: inset 0 0 0 0.12rem var(--theme-bg-deep);
}

#chat .mes[is_user="false"][is_system="false"] .mesAvatarWrapper .mesIDDisplay {
    display: block;
    width: max-content;
    max-width: calc(var(--theme-avatar-size) + 2.4rem);
    margin-block-start: 0.48rem;
    padding: 0.12rem 0.4rem;
    color: var(--theme-text-secondary);
    background-color: var(--theme-surface-muted);
    border: 1px solid var(--theme-border-soft);
    border-radius: var(--theme-radius-sm);
    font-family: var(--theme-font-ui);
    font-size: var(--theme-font-size-meta);
    text-align: center;
    box-shadow: none;
}

#chat .mes[is_user="false"][is_system="false"] .mesAvatarWrapper .mesIDDisplay::before {
    content: "观测层 ";
    color: var(--theme-ink-green);
}

#chat .mes[is_user="false"][is_system="false"] .mesAvatarWrapper :is(.mes_timer, .tokenCounterDisplay) {
    width: max-content;
    max-width: calc(var(--theme-avatar-size) + 2rem);
    padding: 0.08rem 0.35rem;
    color: var(--theme-text-secondary);
    background-color: var(--theme-surface-muted);
    border: 1px solid var(--theme-border-soft);
    border-radius: var(--theme-radius-sm);
    font-family: var(--theme-font-ui);
    font-size: var(--theme-font-size-meta);
    text-align: center;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name {
    position: absolute;
    z-index: 1;
    inset-block-start: var(--theme-city-height);
    inset-inline: 0;
    min-height: 3.15rem;
    margin: 0;
    padding: 0.58rem var(--theme-floor-pad);
    padding-inline-end: calc(var(--theme-avatar-size) + clamp(10rem, 18%, 14rem));
    display: flex;
    align-items: center;
    gap: 0.65rem;
    color: var(--theme-ink-green);
    background-color: var(--theme-surface-muted);
    background-image: var(--theme-paper-image);
    background-size: 24rem 24rem;
    background-blend-mode: multiply;
    border-block: 1px solid var(--theme-border-soft);
    font-family: var(--theme-font-display);
}

#chat .mes[is_user="false"][is_system="false"] .name_text {
    color: var(--theme-ink-green);
    font-size: 1.3em;
    font-weight: 400;
    letter-spacing: 0.1em;
}

#chat .mes[is_user="false"][is_system="false"] .timestamp {
    color: var(--theme-text-secondary);
    font-family: var(--theme-font-ui);
    font-size: var(--theme-font-size-meta);
    letter-spacing: 0.04em;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text {
    position: relative;
    z-index: 1;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text::after {
    content: "";
    display: block;
    width: min(16rem, 50%);
    height: 6rem;
    margin: 1.15rem -0.35rem -0.35rem auto;
    background-image: var(--theme-footer-ornament);
    background-position: right bottom;
    background-repeat: no-repeat;
    background-size: contain;
    pointer-events: none;
}

#chat .mes[is_user="true"] {
    width: calc(100% - clamp(0.5rem, 1.4vw, 1.35rem));
    margin: clamp(0.7rem, 1.4vw, 1rem) auto;
    padding: 0.72rem clamp(0.85rem, 2vw, 1.5rem);
    align-items: center;
    color: var(--theme-text-primary);
    background-color: var(--theme-surface-light);
    background-image: var(--theme-paper-image);
    background-size: 28rem 28rem;
    background-blend-mode: multiply;
    border: 1px solid var(--theme-border);
    border-radius: var(--theme-radius-sm);
    box-shadow: 0 0.35rem 0.85rem rgba(18, 29, 23, 0.28), inset 0 0 0 1px rgba(233, 216, 169, 0.26);
}

#chat .mes[is_user="true"] .mesAvatarWrapper {
    flex: 0 0 3rem;
    width: 3rem;
    margin-inline-end: var(--theme-gap-sm);
}

#chat .mes[is_user="true"] .avatar,
#chat .mes[is_user="true"] .avatar img {
    width: 2.65rem;
    height: 2.65rem;
    flex: 0 0 2.65rem;
    border-radius: 50%;
}

#chat .mes[is_user="true"] .avatar {
    padding: 0.12rem;
    background-color: var(--theme-bg-deep);
    border: 1px solid var(--theme-brass);
    box-shadow: var(--theme-shadow-soft);
}

#chat .mes[is_user="true"] .avatar img {
    object-fit: cover;
    border: 1px solid var(--theme-border);
    box-shadow: none;
}

#chat .mes[is_user="true"] .mes_block {
    flex: 1 1 auto;
    min-width: 0;
    padding: 0;
    overflow: visible;
}

#chat .mes[is_user="true"] .ch_name {
    color: var(--theme-ink-green);
    border-block-end: 1px solid var(--theme-border-soft);
    font-family: var(--theme-font-display);
}

#chat .mes[is_user="true"] .name_text {
    color: var(--theme-ink-green);
    font-size: 1.15em;
    font-weight: 400;
}

#chat .mes[is_system="true"] {
    margin: var(--theme-gap-sm) var(--theme-gap-lg);
    padding: var(--theme-gap-sm) var(--theme-gap-md);
    color: var(--theme-text-secondary);
    background-color: var(--theme-surface-muted);
    border-inline-start: 0.25rem solid var(--theme-brass);
}

#chat .mes .mes_buttons,
#chat .mes .mes_edit_buttons,
#chat .mes .mes_reasoning_actions {
    position: relative;
    z-index: 5;
}

#chat .swipe_left,
#chat .swipeRightBlock {
    color: var(--theme-brass);
}

#chat .swipes-counter {
    color: var(--theme-text-secondary);
    font-family: var(--theme-font-ui);
}

/* v6 手机正文轴：头像释放侧槽，正文回到完整消息宽度并保持对称内距。 */
@media (max-width: 700px) {
    #chat .mes[is_system="false"] {
        flex-direction: column;
        align-items: stretch;
    }

    #chat .mes[is_system="false"] > .mesAvatarWrapper {
        align-self: center;
        margin-inline: auto;
    }

    #chat .mes[is_system="false"] > .mes_block {
        inline-size: 100%;
        min-inline-size: 0;
    }

    #chat .mes[is_system="false"] > .mes_block > .mes_text {
        inline-size: min(100%, var(--st-theme-mobile-reading-width));
        max-inline-size: 100%;
        margin-inline: auto !important;
        padding-inline: var(--st-theme-mobile-reading-padding) !important;
        box-sizing: border-box;
    }
}

/* ===== src/full-text.css ===== */
/* T06 文献排版：只处理正文语义，不移动头像或消息外壳。 */
#chat .mes_text {
    color: var(--theme-text-primary);
    font-family: var(--theme-font-body);
    font-size: var(--theme-font-size-body);
    font-weight: 400;
    line-height: 1.9;
    letter-spacing: 0.035em;
    overflow-wrap: anywhere;
}

#chat .mes[is_user="true"] .mes_text {
    font-size: var(--theme-font-size-user);
    line-height: 1.72;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text {
    font-size: var(--theme-font-size-character);
    width: 100%;
    max-width: 100%;
    margin-inline: auto;
}

#chat .mes_text :is(h1, h2, h3, h4, h5, h6) {
    color: var(--theme-ink-green);
    font-family: var(--theme-font-display);
    font-weight: 400;
    line-height: 1.35;
    letter-spacing: 0.08em;
}

#chat .mes_text :is(h1, h2) {
    padding-block-end: 0.35em;
    border-block-end: 1px solid var(--theme-border-soft);
}

#chat .mes_text p {
    margin-block: 0 1.05em;
}

#chat .mes_text :is(strong, b) {
    color: var(--theme-rust);
    font-family: var(--theme-font-display);
    font-weight: 400;
    letter-spacing: 0.06em;
}

#chat .mes_text :is(em, i) {
    color: var(--theme-ink-green-soft);
}

#chat .mes_text a {
    color: var(--theme-rust);
    text-decoration-color: var(--theme-brass);
    text-underline-offset: 0.18em;
}

#chat .mes_text blockquote {
    margin: 1.1em 0;
    padding: 0.7em 1em;
    color: var(--theme-text-secondary);
    background-color: var(--theme-surface-muted);
    border-inline-start: 0.25rem solid var(--theme-brass);
}

#chat .mes_text :is(ul, ol) {
    padding-inline-start: 1.55em;
}

#chat .mes_text li::marker {
    color: var(--theme-brass);
}

#chat .mes_text hr {
    height: 1px;
    margin: 1.4em 0;
    background: linear-gradient(90deg, transparent, var(--theme-border), transparent);
    border: none;
    opacity: 1;
}

#chat .mes_text :is(code, kbd, samp) {
    color: var(--theme-surface);
    background-color: var(--theme-ink-green);
    border: 1px solid var(--theme-brass);
    border-radius: var(--theme-radius-sm);
    font-family: "Courier New", monospace;
}

#chat .mes_text code:not(.hljs) {
    color: var(--theme-text-on-dark);
    background-color: var(--theme-ink-green);
    border-color: var(--theme-brass);
    text-shadow: var(--theme-text-shadow-none);
}

#chat .mes_text code {
    padding: 0.12em 0.35em;
}

#chat .mes_text pre {
    max-width: 100%;
    padding: 0.9em;
    overflow-x: var(--theme-overflow-x);
    color: var(--theme-surface);
    background-color: var(--theme-bg-deep);
    border: 1px solid var(--theme-brass);
    border-radius: var(--theme-radius-md);
    box-shadow: var(--theme-shadow-none);
}

#chat .mes_text pre code.hljs {
    color: var(--theme-text-on-dark) !important;
    background-color: var(--theme-bg-deep) !important;
    border-color: var(--theme-brass) !important;
    opacity: var(--theme-opacity-full) !important;
    filter: var(--theme-filter-none) !important;
    text-shadow: var(--theme-text-shadow-none) !important;
}

#chat .mes_text pre code.hljs :is(.hljs-operator, .hljs-punctuation, .hljs-subst) {
    color: var(--theme-text-on-dark) !important;
    opacity: var(--theme-opacity-full) !important;
    text-shadow: var(--theme-text-shadow-none) !important;
}

