#chat .mes[is_user="true"] {
    background-blend-mode: multiply;
}

/* ===== src/windows/mobile.css ===== */
/* W14 独立390px合同；不改.drawer父级几何。 */
@media screen and (max-width: 700px) {
    :root {
        --theme-avatar-size: 4.8rem;
        --theme-avatar-gap: 0.45rem;
        --theme-city-height: 6.5rem;
        --theme-floor-pad: 0.72rem;
    }

    #chat {
        padding: 0.25rem;
        border-inline: none;
        box-shadow: none;
    }

    #chat .mes {
        padding: 0;
    }

    #chat .mes[is_user="false"][is_system="false"] {
        width: calc(100% - 0.3rem);
        margin-block: 0.55rem;
    }

    #chat .mes[is_user="false"][is_system="false"] .mes_block {
        padding: calc(var(--theme-city-height) + 3.8rem) 0.72rem 0.85rem;
        background-size: 100% var(--theme-city-height), 24rem 24rem, 100% 100%;
    }

    #chat .mes[is_user="false"][is_system="false"] .mesAvatarWrapper {
        inset-block-start: calc(var(--theme-city-height) - (var(--theme-avatar-size) * 0.5));
        inset-inline-end: 1.15rem;
    }

    #chat .mes[is_user="false"][is_system="false"] .mes_block::before {
        inset-block-start: calc(var(--theme-city-height) + 0.42rem);
        inset-inline-end: 0.4rem;
        padding: 0.2rem 0.4rem;
    }

    #chat .mes[is_user="false"][is_system="false"] .ch_name {
        min-height: 2.55rem;
        margin: 0;
        padding: 0.42rem 0.72rem;
        padding-inline-end: calc(var(--theme-avatar-slot) + 2.1rem);
    }

    #chat .mes[is_user="false"][is_system="false"] .name_text {
        font-size: 1.08em;
        letter-spacing: 0.04em;
    }

    #chat .mes[is_user="true"] {
        width: calc(100% - 0.3rem);
        margin: 0.5rem auto;
        padding: 0.55rem 0.65rem;
    }

    #chat .mes[is_user="true"] .mesAvatarWrapper {
        flex-basis: 2.35rem;
        width: 2.35rem;
    }

    #chat .mes[is_user="true"] .avatar,
    #chat .mes[is_user="true"] .avatar img {
        width: 2.1rem;
        height: 2.1rem;
        flex-basis: 2.1rem;
    }

    #chat .mes_text {
        line-height: 1.78;
        letter-spacing: 0.02em;
    }

    #chat .mes[is_user="false"][is_system="false"] .mes_text::after {
        width: min(10rem, 58%);
        height: 4.2rem;
    }

    #top-settings-holder .drawer-icon {
        padding: 0.08rem;
        font-size: var(--topBarIconSize);
    }

    #send_form {
        border-radius: var(--theme-radius-sm);
        box-shadow: none;
    }

    #send_form #nonQRFormItems,
    #send_form :is(#leftSendForm, #rightSendForm) {
        flex-wrap: nowrap;
        column-gap: 0.15rem;
    }

    #send_form #send_textarea {
        min-width: 0;
        padding-inline: 0.35rem;
    }

    #completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
        grid-template-columns: minmax(0, 1fr) auto auto;
        gap: 0.3rem;
    }

    .select2-dropdown,
    .popup {
        max-width: 100%;
    }
}

