/*
 * 远程字体失败时回退到本机宋体/楷体；远程城市与纸张素材失败时，
 * tokens中的none让纯色、边框和渐变继续承担全部可读性与交互。
 */
#chat {
    background-color: var(--theme-bg-deep);
}

#chat .mes_block {
    background-color: var(--theme-surface);
}
